import { type Lch, lchToRgb, MAX_CHROMA, rgbToLch } from '../core/colourAdjust';
import { type BeadColour, type Rgb, rgbToHex } from '../core/pattern';
import { confirmDialog, h } from './dom';

export type AdjustResult = { kind: 'colour'; rgb: Rgb } | { kind: 'merge'; into: number } | null;

export interface AdjustOptions {
  colour: BeadColour;
  /** The colour as generated by the last build, for Przywróć. */
  generated: Rgb;
  /** Shows a candidate colour in the pattern preview; null restores the pattern as it is. */
  onPreview: (rgb: Rgb | null) => void;
  /** Palette index of another bead colour with exactly this colour, or -1. */
  findMatch: (rgb: Rgb) => number;
  labelOf: (index: number) => string;
}

/**
 * Colour Adjustment dialog: lightness, hue and saturation sliders in a perceptual space, with the pattern
 * preview following live. Resolves with the new colour, a merge into an identical colour, or null.
 */
export function adjustColourDialog({ colour, generated, onPreview, findMatch, labelOf }: AdjustOptions): Promise<AdjustResult> {
  return new Promise((resolve) => {
    // Kept exactly (not via LCh) until a slider moves, so an untouched colour comes back unchanged.
    let rgb = colour.rgb;
    let result: AdjustResult = null;
    let frame = 0;

    const before = h('span', { class: 'adjust-swatch', style: { backgroundColor: rgbToHex(colour.rgb) } });
    const after = h('span', { class: 'adjust-swatch' });
    const hex = h('span', { class: 'muted small' });

    const slider = (label: string, max: number, step: number) => {
      const input = h('input', { type: 'range', class: 'slider', min: '0', max: String(max), step: String(step), oninput: onSlide });
      return { input, element: h('label', { class: 'field' }, h('span', {}, label), input) };
    };
    const lightness = slider('Jasność', 100, 0.5);
    const hue = slider('Odcień', 360, 1);
    const chroma = slider('Nasycenie', MAX_CHROMA, 0.5);

    function setSliders(lch: Lch) {
      lightness.input.value = String(lch.l);
      hue.input.value = String(lch.h);
      chroma.input.value = String(lch.c);
    }

    function show() {
      after.style.backgroundColor = rgbToHex(rgb);
      hex.textContent = rgbToHex(rgb);
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        onPreview(rgb);
      });
    }

    function onSlide() {
      rgb = lchToRgb({ l: Number(lightness.input.value), c: Number(chroma.input.value), h: Number(hue.input.value) });
      show();
    }

    function onRestore() {
      rgb = generated;
      setSliders(rgbToLch(rgb));
      show();
    }

    async function onApply() {
      const match = findMatch(rgb);
      if (match >= 0) {
        const merge = await confirmDialog(`Ten kolor jest już w palecie jako „${labelOf(match)}” — połączyć?`, 'Połącz');
        if (!merge) return;
        result = { kind: 'merge', into: match };
      } else {
        result = { kind: 'colour', rgb };
      }
      dialog.close();
    }

    const dialog = h(
      'dialog',
      { class: 'dialog adjust-dialog' },
      h(
        'div',
        { class: 'dialog-body' },
        h('p', {}, `Kolor „${colour.label}”`),
        h('div', { class: 'adjust-compare' }, before, after, hex),
        lightness.element,
        hue.element,
        chroma.element,
      ),
      h(
        'div',
        { class: 'dialog-actions' },
        h('button', { class: 'btn btn-primary', onclick: onApply }, 'Zastosuj'),
        h('button', { class: 'btn', onclick: onRestore }, 'Przywróć'),
        h('button', { class: 'btn', onclick: () => dialog.close() }, 'Anuluj'),
      ),
    );
    dialog.addEventListener('close', () => {
      cancelAnimationFrame(frame);
      onPreview(null);
      dialog.remove();
      resolve(result);
    });

    setSliders(rgbToLch(rgb));
    show();
    document.body.appendChild(dialog);
    dialog.showModal();
  });
}
